def _static_files_configuration_check_case_keys(case: Any) -> set[str]:
    keys = set(STATIC_FILES_CONFIGURATION_CHECK_CASE_KEYS)
    if isinstance(case, dict) and "directory_pathlike" in case:
        keys.add("directory_pathlike")
    return keys


